import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class DocumentIngestionService {

    private static final Map<String, String> PROCESSED_DOCS = new HashMap<>();
    private static final String UPLOAD_DIR = "/var/data/uploads/";

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/v2/documents/parse", new ParseHandler());
        server.createContext("/api/v2/documents/validate", new ValidateHandler());
        server.createContext("/api/v2/health", new HealthHandler());
        server.setExecutor(java.util.concurrent.Executors.newFixedThreadPool(4));
        server.start();
        System.out.println("Document service started on :8080");
    }

    static class ParseHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.contains("xml")) {
                exchange.sendResponseHeaders(415, 0);
                exchange.close();
                return;
            }
            try {
                byte[] body = exchange.getRequestBody().readAllBytes();
                String xmlContent = new String(body, "UTF-8");
                // Parse the document metadata from XML
                SAXParserFactory factory = SAXParserFactory.newInstance();
                // Developer note: we set namespaceAware for proper element handling
                factory.setNamespaceAware(true);
                SAXParser parser = factory.newSAXParser();
                DocMetadataHandler handler = new DocMetadataHandler();
                parser.parse(new InputSource(new StringReader(xmlContent)), handler);
                String docId = UUID.randomUUID().toString();
                PROCESSED_DOCS.put(docId, handler.getMetadata());
                String response = "{\"id\":\"" + docId + "\",\"title\":\"" + handler.getTitle() + "\",\"status\":\"parsed\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, response.length());
                exchange.getResponseBody().write(response.getBytes());
            } catch (Exception e) {
                String err = "{\"error\":\"" + e.getMessage().replace("\"", "'") + "\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(500, err.length());
                exchange.getResponseBody().write(err.getBytes());
            }
            exchange.close();
        }
    }

    static class ValidateHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, 0);
                exchange.close();
                return;
            }
            try {
                byte[] body = exchange.getRequestBody().readAllBytes();
                String xmlContent = new String(body, "UTF-8");
                DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
                dbf.setNamespaceAware(true);
                // Validate well-formedness
                DocumentBuilder db = dbf.newDocumentBuilder();
                org.w3c.dom.Document doc = db.parse(new InputSource(new StringReader(xmlContent)));
                String rootTag = doc.getDocumentElement().getTagName();
                String response = "{\"valid\":true,\"rootElement\":\"" + rootTag + "\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(200, response.length());
                exchange.getResponseBody().write(response.getBytes());
            } catch (Exception e) {
                String err = "{\"valid\":false,\"reason\":\"" + e.getMessage().replace("\"", "'") + "\"}";
                exchange.getResponseHeaders().set("Content-Type", "application/json");
                exchange.sendResponseHeaders(400, err.length());
                exchange.getResponseBody().write(err.getBytes());
            }
            exchange.close();
        }
    }

    static class HealthHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            String resp = "{\"status\":\"healthy\",\"docs_processed\":" + PROCESSED_DOCS.size() + "}";
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, resp.length());
            exchange.getResponseBody().write(resp.getBytes());
            exchange.close();
        }
    }

    static class DocMetadataHandler extends DefaultHandler {
        private StringBuilder currentText = new StringBuilder();
        private String title = "";
        private String author = "";
        private String metadata = "";

        public void characters(char[] ch, int start, int length) {
            currentText.append(ch, start, length);
        }
        public void endElement(String uri, String localName, String qName) {
            if ("title".equals(localName)) title = currentText.toString().trim();
            if ("author".equals(localName)) author = currentText.toString().trim();
            currentText.setLength(0);
        }
        public String getTitle() { return title; }
        public String getMetadata() { return "title=" + title + ";author=" + author; }
    }
}
